from decimal import Decimal
from django.conf import settings
from django.db import migrations, models
from django.db.models import F, Sum


def preencher_os_pagas_no_cartao(apps, schema_editor):
    """OS já pagas no cartão recebem o acréscimo com o percentual configurado hoje (o mesmo que a tela mostrava)."""
    OrdemServico = apps.get_model('core', 'OrdemServico')
    fator = Decimal(settings.ACRESCIMO_CARTAO)
    ordens = (OrdemServico.objects.filter(status='paga', forma_pagamento='cartao')
              .annotate(valor=Sum(F('itens__quantidade') * F('itens__preco_unitario'), default=0)))
    for o in ordens:
        total = Decimal(o.valor)
        OrdemServico.objects.filter(pk=o.pk).update(
            acrescimo_cartao=(total * fator).quantize(Decimal('0.01')) - total)


